"""A project served through a detour (design specification section 9.13).

The WSGI application says which instance served it and what the request
looked like to it, answers /page with an HTML page, and raises on /boom;
an ASGI mount echoes WebSocket
messages under /ws; and where grpcio is installed the tests add a gRPC
mount whose greeter says the same. greeter_pb2 and greeter_pb2_grpc are
generated by the tests.
"""

from __future__ import annotations

import json
import os
from collections.abc import Callable, Iterable
from typing import Any


def wsgi_app(environ: dict[str, Any], start_response: Callable[..., Any]) -> Iterable[bytes]:
    """Report the instance and the request, answer /page with HTML, or
    raise on /boom."""

    if environ["PATH_INFO"] == "/boom":
        raise RuntimeError("boom from the detoured fixture")

    if environ["PATH_INFO"] == "/page":
        page = b"<!doctype html><html><head><title>page</title></head><body>page</body></html>"
        start_response(
            "200 OK",
            [("Content-Type", "text/html; charset=utf-8"), ("Content-Length", str(len(page)))],
        )
        return [page]

    body = json.dumps(
        {
            "instance": os.environ.get("MURU_INSTANCE_TAG", ""),
            "host": environ.get("HTTP_HOST", ""),
            "scheme": environ["wsgi.url_scheme"],
            "remote_addr": environ.get("REMOTE_ADDR", ""),
            "server_port": environ.get("SERVER_PORT", ""),
            "request_id": environ.get("muru.request_id", ""),
            "cookie": environ.get("HTTP_COOKIE", ""),
            "preview": environ.get("HTTP_MURU_PREVIEW", ""),
            "data_dir": os.environ.get("MURU_DATA_DIR", ""),
        }
    ).encode()
    start_response(
        "200 OK", [("Content-Type", "application/json"), ("Content-Length", str(len(body)))]
    )

    return [body]


async def asgi_app(scope: dict[str, Any], receive: Any, send: Any) -> None:
    """Echo WebSocket messages, prefixed with the instance that echoed them."""

    if scope["type"] == "lifespan":
        while True:
            message = await receive()

            if message["type"] == "lifespan.startup":
                await send({"type": "lifespan.startup.complete"})
            elif message["type"] == "lifespan.shutdown":
                await send({"type": "lifespan.shutdown.complete"})
                return

    if scope["type"] != "websocket":
        return

    message = await receive()
    assert message["type"] == "websocket.connect"
    await send({"type": "websocket.accept"})
    instance = os.environ.get("MURU_INSTANCE_TAG", "")

    while True:
        message = await receive()

        if message["type"] == "websocket.disconnect":
            return

        await send({"type": "websocket.send", "text": f"{instance} {message.get('text', '')}"})


def register(server: Any) -> None:
    """Register the greeter, which answers with the instance that served it."""

    import greeter_pb2
    import greeter_pb2_grpc

    class Greeter(greeter_pb2_grpc.GreeterServicer):  # type: ignore[misc]
        def SayHello(self, request: Any, context: Any) -> Any:
            instance = os.environ.get("MURU_INSTANCE_TAG", "")
            return greeter_pb2.Reply(message=f"{instance} {request.name}")

    greeter_pb2_grpc.add_GreeterServicer_to_server(Greeter(), server)
